"use strict";const utils=require("../utils");module.exports=function(defaultFuncs,api,ctx){return async function getThemeInfo(identifier,callback){if(!identifier){const error=new Error("identifier is required (threadID or themeID)");if(callback)return callback(error);throw error}let resolveFunc,rejectFunc;const promise=new Promise((resolve,reject)=>{resolveFunc=resolve;rejectFunc=reject});const isThemeID=/^\d{10,}$/.test(identifier.toString());if(isThemeID){try{const themeData=await api.fetchThemeData(identifier);if(callback){callback(null,themeData)}else{resolveFunc(themeData)}return promise}catch(err){utils.error("getThemeInfo - fetchThemeData",err)}}try{let threadInfo;try{threadInfo=await api.getThreadInfo(identifier)}catch(getInfoErr){const themeInfo={threadID:identifier,threadName:"",color:null,emoji:"👍",theme_id:null,theme_color:null,gradient_colors:null,is_default:true,error:getInfoErr.message||"Could not retrieve full thread info"};if(callback){return callback(null,themeInfo)}else{return resolveFunc(themeInfo)}}if(!threadInfo||Array.isArray(threadInfo)&&threadInfo.length===0){const themeInfo={threadID:identifier,threadName:"",color:null,emoji:"👍",theme_id:null,theme_color:null,gradient_colors:null,is_default:true};if(callback){return callback(null,themeInfo)}else{return resolveFunc(themeInfo)}}const info=Array.isArray(threadInfo)?threadInfo[0]:threadInfo;const themeId=info.theme_id||info.threadTheme&&info.threadTheme.id||info.themeID||null;const themeInfo={threadID:identifier,threadName:info.threadName||info.name||"",color:info.color||null,emoji:info.emoji||"👍",theme_id:themeId,theme_fbid:themeId,theme_color:info.theme_color||info.color||null,gradient_colors:info.gradient_colors||null,threadTheme:info.threadTheme||null,is_default:!info.color&&!themeId};if(callback){callback(null,themeInfo)}else{resolveFunc(themeInfo)}}catch(err){utils.error("getThemeInfo",err);if(callback){callback(err)}else{rejectFunc(err)}}return promise}};
